result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/prodline/config.py", "content": """"Pipeline configuration loading."""

from __future__ import annotations

from dataclasses import dataclass
from pathlib import Path

import yaml


@dataclass(frozen=True)
class Config:
    input_dir: Path
    work_dir: Path
    rules_file: Path
    bates_prefix: str = "PROD-"
    bates_padding: int = 6

    @property
    def manifest_path(self) -> Path:
        return self.work_dir / "manifest.json"

    @property
    def stamped_dir(self) -> Path:
        return self.work_dir / "stamped"

    @property
    def redacted_dir(self) -> Path:
        return self.work_dir / "redacted"

    @property
    def index_path(self) -> Path:
        return self.work_dir / "index.db"

    @property
    def audit_path(self) -> Path:
        return self.work_dir / "audit.jsonl"


def load_config(path: str | Path) -> Config:
    raw = yaml.safe_load(Path(path).read_text(encoding="utf-8")) or {}
    try:
        return Config(
            input_dir=Path(raw["input_dir"]),
            work_dir=Path(raw["work_dir"]),
            rules_file=Path(raw["rules_file"]),
            bates_prefix=str(raw.get("bates_prefix", "PROD-")),
            bates_padding=int(raw.get("bates_padding", 6)),
        )
    except KeyError as exc:  # pragma: no cover - config authoring error
        raise ValueError(f"config missing required key: {exc}") from exc
"})
