result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/prodline/audit.py", "content": """"Hash-chained JSONL audit log.

Every pipeline stage appends one record. Each record carries the sha256 of
the previous record, so any mutation of history breaks verification.
"""

from __future__ import annotations

import hashlib
import json
from pathlib import Path
from typing import Any

GENESIS_HASH = "0" * 64


def _canonical(obj: Any) -> bytes:
    return json.dumps(obj, sort_keys=True, separators=(",", ":")).encode("utf-8")


def _record_hash(record: dict[str, Any]) -> str:
    body = {k: v for k, v in record.items() if k != "hash"}
    return hashlib.sha256(_canonical(body)).hexdigest()


class AuditLog:
    def __init__(self, path: str | Path):
        self.path = Path(path)

    def append(self, stage: str, payload: dict[str, Any]) -> dict[str, Any]:
        records = self.read_all()
        prev_hash = records[-1]["hash"] if records else GENESIS_HASH
        record: dict[str, Any] = {
            "seq": len(records),
            "stage": stage,
            "payload": payload,
            "prev_hash": prev_hash,
        }
        record["hash"] = _record_hash(record)
        self.path.parent.mkdir(parents=True, exist_ok=True)
        with self.path.open("a", encoding="utf-8") as fh:
            fh.write(json.dumps(record, sort_keys=True) + "\n")
        return record

    def read_all(self) -> list[dict[str, Any]]:
        if not self.path.exists():
            return []
        out = []
        for line in self.path.read_text(encoding="utf-8").splitlines():
            line = line.strip()
            if line:
                out.append(json.loads(line))
        return out

    def verify(self) -> tuple[bool, str | None]:
        """Return (ok, first_bad_seq_or_None)."""
        prev_hash = GENESIS_HASH
        for expected_seq, record in enumerate(self.read_all()):
            if (
                record.get("seq") != expected_seq
                or record.get("prev_hash") != prev_hash
                or record.get("hash") != _record_hash(record)
            ):
                return False, record.get("seq", expected_seq)
            prev_hash = record["hash"]
        return True, None
"})
