result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/prodline/redactor.py", "content": """"Redactor stage: apply regex rules from rules.yaml, fail-closed re-scan.

Rules file format (YAML):

    rules:
      - name: ssn
        pattern: "\\d{3}-\\d{2}-\\d{4}"
        replacement: "[REDACTED-SSN]"

Fail-closed guarantees:
  * every rule regex is compiled before any output is written;
  * after redaction, all written files are re-scanned with the same
    patterns — any residual match aborts the stage;
  * any failure removes the entire redacted/ output directory.
"""

from __future__ import annotations

import re
import shutil
from pathlib import Path

import yaml

from .audit import AuditLog
from .config import Config


class RedactionError(RuntimeError):
    """Raised on invalid rule regexes or residual matches after redaction."""


def load_rules(rules_file: str | Path) -> list[tuple[str, re.Pattern[str], str]]:
    raw = yaml.safe_load(Path(rules_file).read_text(encoding="utf-8")) or {}
    compiled: list[tuple[str, re.Pattern[str], str]] = []
    for i, rule in enumerate(raw.get("rules") or []):
        name = str(rule.get("name", f"rule-{i}"))
        pattern = rule.get("pattern")
        if not pattern:
            raise RedactionError(f"rule {name!r}: missing pattern")
        try:
            compiled.append((name, re.compile(pattern), str(rule.get("replacement", "[REDACTED]"))))
        except re.error as exc:
            raise RedactionError(f"rule {name!r}: invalid regex: {exc}") from exc
    return compiled


def _page_files(root: Path) -> list[Path]:
    return sorted(p for p in root.rglob("*.txt") if p.is_file())


def redact(config: Config, audit: AuditLog) -> dict[str, int]:
    out_dir = config.redacted_dir
    try:
        # Compile everything up front; an invalid regex aborts before any I/O.
        rules = load_rules(config.rules_file)

        stamped_root = config.stamped_dir
        pages = _page_files(stamped_root)
        if not pages:
            raise RedactionError("no stamped pages found to redact")

        if out_dir.exists():
            shutil.rmtree(out_dir)

        total_hits = 0
        for page in pages:
            rel = page.relative_to(stamped_root)
            text = page.read_text(encoding="utf-8")
            hits_in_page = 0
            for _name, rx, replacement in rules:
                text, n = rx.subn(replacement, text)
                hits_in_page += n
            total_hits += hits_in_page
            dest = out_dir / rel
            dest.parent.mkdir(parents=True, exist_ok=True)
            dest.write_text(text, encoding="utf-8")

        # Fail-closed re-scan: nothing may survive.
        residuals: list[str] = []
        for produced in _page_files(out_dir):
            body = produced.read_text(encoding="utf-8")
            for name, rx, _replacement in rules:
                if rx.search(body):
                    residuals.append(f"{produced.relative_to(out_dir)}: rule {name!r}")
        if residuals:
            raise RedactionError(
                "fail-closed: residual matches after redaction: " + "; ".join(residuals)
            )

        audit.append(
            "redact",
            {"rules": [name for name, _rx, _r in rules], "pages": len(pages), "hits": total_hits},
        )
        return {"pages": len(pages), "hits": total_hits}
    except Exception:
        # No partial outputs may survive a failed redaction stage.
        shutil.rmtree(out_dir, ignore_errors=True)
        raise
"})
